'use client'

import { useEffect, useId, useRef, useState, type ReactNode } from 'react'
import './reveal-footer.css'

export interface RevealFooterLink {
  label: string
  href: string
}

export interface RevealFooterProps {
  /** Opaque page content that scrolls away to uncover the footer. */
  children?: ReactNode
  title: string
  brand: string
  contact: RevealFooterLink
  availability?: string
  links?: RevealFooterLink[]
  note?: string
  legal?: string
  reveal?: boolean
  className?: string
}

function findScrollViewport(element: HTMLElement) {
  let parent = element.parentElement
  while (parent && parent !== document.body) {
    if (/(auto|scroll|overlay)/.test(window.getComputedStyle(parent).overflowY)) return parent
    parent = parent.parentElement
  }
  return null
}

/** A native-scroll footer, confined to its own content and nearest scroll viewport. */
export function RevealFooter({ children, title, brand, contact, availability, links = [], note, legal, reveal = true, className = '' }: RevealFooterProps) {
  const root = useRef<HTMLDivElement>(null)
  const footer = useRef<HTMLElement>(null)
  const titleId = useId()
  const [canReveal, setCanReveal] = useState(false)

  useEffect(() => {
    const element = root.current
    const foot = footer.current
    if (!element || !foot || !reveal || !children) {
      setCanReveal(false)
      return
    }
    const viewport = findScrollViewport(element)
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)')
    let frame = 0
    function measure() {
      frame = 0
      const availableHeight = viewport?.clientHeight ?? window.innerHeight
      // A footer taller than its scrollport must remain in normal flow.
      const fits = element!.clientWidth > 600 && foot!.getBoundingClientRect().height + 24 < availableHeight
      setCanReveal(fits && !reducedMotion.matches)
    }
    function scheduleMeasure() {
      if (!frame) frame = window.requestAnimationFrame(measure)
    }
    measure()
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleMeasure)
    observer?.observe(foot)
    observer?.observe(element)
    if (viewport) observer?.observe(viewport)
    window.addEventListener('resize', scheduleMeasure)
    reducedMotion.addEventListener('change', scheduleMeasure)
    return () => {
      observer?.disconnect()
      window.removeEventListener('resize', scheduleMeasure)
      reducedMotion.removeEventListener('change', scheduleMeasure)
      window.cancelAnimationFrame(frame)
    }
  }, [reveal, children])

  return <div ref={root} className={`ac-reveal-footer ${className}`.trim()} data-reveal={canReveal ? 'true' : 'false'}>
    {children && <div className="ac-reveal-footer-content">{children}</div>}
    <footer
      ref={footer}
      className="ac-reveal-footer-panel"
      aria-labelledby={titleId}
      onFocusCapture={(event) => {
        // :focus-within removes the overlap before bringing a keyboard target into view.
        if (event.target instanceof HTMLElement) event.target.scrollIntoView({ block: 'nearest', behavior: 'instant' })
      }}
    >
      <div className="ac-reveal-footer-topline"><span>THE NEXT CHAPTER</span>{availability && <span className="ac-reveal-footer-availability"><i aria-hidden="true" />{availability}</span>}</div>
      <div className="ac-reveal-footer-invitation">
        <h2 id={titleId}>{title}</h2>
        <a className="ac-reveal-footer-contact" href={contact.href}><span>{contact.label}</span><span aria-hidden="true">↗</span></a>
      </div>
      <div className="ac-reveal-footer-details">{note && <p>{note}</p>}{links.length > 0 && <ul aria-label="More ways to connect">{links.map((link, index) => <li key={`${link.href}-${index}`}><a href={link.href}>{link.label}<span aria-hidden="true">↗</span></a></li>)}</ul>}</div>
      <div className="ac-reveal-footer-wordmark"><span className="ac-reveal-footer-brand">{brand}</span><span className="ac-reveal-footer-registered" aria-hidden="true">®</span></div>
      {legal && <p className="ac-reveal-footer-legal">{legal}</p>}
    </footer>
  </div>
}

.ac-reveal-footer {
  --ac-footer-surface: #271b28;
  --ac-footer-ink: #f5cee1;
  --ac-footer-muted: #c4aabc;
  --ac-footer-line: #f5cee130;
  --ac-footer-accent: #d9f884;
  --ac-footer-content: #eee9df;
  container: ac-reveal-footer / inline-size;
  position: relative;
  isolation: isolate;
  width: 100%;
  color: var(--ac-footer-ink);
  background: var(--ac-footer-surface);
  font-family: var(--sans, Arial, sans-serif);
  text-align: left;
}
.ac-reveal-footer *, .ac-reveal-footer *::before, .ac-reveal-footer *::after { box-sizing: border-box; }
.ac-reveal-footer-content { position: relative; z-index: 2; display: flow-root; background: var(--ac-footer-content); }
.ac-reveal-footer-panel { position: relative; z-index: 1; padding: clamp(24px, 3cqi, 48px); background: var(--ac-footer-surface); }
.ac-reveal-footer[data-reveal="true"] .ac-reveal-footer-panel { position: sticky; bottom: 0; }
.ac-reveal-footer[data-reveal="true"] .ac-reveal-footer-panel:focus-within { position: relative; }
.ac-reveal-footer-topline { display: flex; justify-content: space-between; align-items: center; gap: 18px; flex-wrap: wrap; font-size: clamp(9px, .72cqi, 12px); line-height: 1.5; letter-spacing: .1em; }
.ac-reveal-footer-availability { display: flex; align-items: center; gap: 8px; color: var(--ac-footer-muted); letter-spacing: .015em; }
.ac-reveal-footer-availability i { width: 6px; height: 6px; flex: 0 0 auto; background: var(--ac-footer-accent); border-radius: 50%; }
.ac-reveal-footer-invitation { display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; padding-block: clamp(28px, 3cqi, 56px) clamp(22px, 2cqi, 36px); }
.ac-reveal-footer-invitation h2 { max-width: 11.5ch; margin: 0; font-size: clamp(40px, 6.8cqi, 116px); line-height: .97; letter-spacing: -.07em; font-weight: 400; white-space: pre-line; overflow-wrap: anywhere; }
.ac-reveal-footer a { color: inherit; text-decoration: none; scroll-margin-block: 12px; }
.ac-reveal-footer a:focus-visible { outline: 2px solid var(--ac-footer-accent); outline-offset: 5px; }
.ac-reveal-footer-contact { display: flex; align-items: center; justify-content: space-between; gap: 22px; flex: 0 1 290px; min-width: 0; min-height: 44px; padding: 16px 0; border-bottom: 1px solid var(--ac-footer-ink); font-size: clamp(12px, 1.12cqi, 18px); line-height: 1.4; }
.ac-reveal-footer-contact > span:first-child { overflow-wrap: anywhere; }
.ac-reveal-footer-contact > span:last-child { font-size: 28px; transition: transform .2s; }
.ac-reveal-footer-contact:hover > span:last-child { transform: translate(3px, -3px); }
.ac-reveal-footer-details { display: flex; align-items: flex-start; justify-content: space-between; gap: 25px; padding-block: 18px 23px; border-top: 1px solid var(--ac-footer-line); color: var(--ac-footer-muted); font-size: clamp(10px, .82cqi, 13px); line-height: 1.65; }
.ac-reveal-footer-details p { max-width: 34ch; margin: 0; }
.ac-reveal-footer-details ul { display: flex; flex-wrap: wrap; gap: 12px 26px; justify-content: flex-end; padding: 0; margin: 0; list-style: none; }
.ac-reveal-footer-details a { display: inline-flex; min-height: 44px; align-items: center; gap: 14px; }
.ac-reveal-footer-details a:hover { color: var(--ac-footer-ink); }
.ac-reveal-footer-wordmark { display: flex; align-items: flex-start; gap: .025em; width: 100%; margin-top: 5px; font-size: clamp(44px, 12.1cqi, 200px); font-weight: 600; line-height: .82; letter-spacing: -.09em; overflow-wrap: anywhere; }
.ac-reveal-footer-brand { min-width: 0; }
.ac-reveal-footer-registered { margin-top: .12em; font-size: .12em; letter-spacing: 0; }
.ac-reveal-footer-legal { display: block; margin: 24px 0 0; color: var(--ac-footer-muted); font-size: clamp(9px, .65cqi, 11px); line-height: 1.5; letter-spacing: .035em; }
@container ac-reveal-footer (max-width: 600px) {
  .ac-reveal-footer-invitation { display: block; }
  .ac-reveal-footer-invitation h2 { font-size: clamp(40px, 10cqi, 60px); }
  .ac-reveal-footer-contact { max-width: 300px; margin-top: 22px; padding-block: 12px; }
  .ac-reveal-footer-details { display: block; }
  .ac-reveal-footer-details ul { justify-content: flex-start; margin-top: 15px; gap: 8px 22px; }
  .ac-reveal-footer-wordmark { font-size: 12.75cqi; }
}
@media (prefers-reduced-motion: reduce) {
  .ac-reveal-footer[data-reveal="true"] .ac-reveal-footer-panel { position: relative; }
  .ac-reveal-footer-contact > span:last-child { transition: none; }
  .ac-reveal-footer-contact:hover > span:last-child { transform: none; }
}
